use alloc::format;
use alloc::vec;
use alloc::vec::Vec;

use flow::FlowId;
use harness::{BackgroundWork, Description, Event, Identifiable, Observable, WorkId, WorkKind};
use process::{Answer, Caller, Giving, Processable, Unremembered};

impl Identifiable for Hook {
    fn identify(&self) -> FlowId {
        match self {
            Hook::SessionStart(start) => start.session_id.identify(),
            Hook::UserPromptSubmit(session) | Hook::PermissionRequest(session) | Hook::PostToolUse(session) => session.identify(),
            Hook::Stop(stop) => stop.session_id.identify(),
            Hook::SessionEnd(end) => end.session_id.identify(),
        }
    }
}

impl Observable for Hook {
    fn events(&self) -> Vec<Event> {
        match self {
            // A resume is Resumed, followed by its context's size; a compaction gives no event from the hook.
            Hook::SessionStart(start) => match &start.source {
                Source::Startup => vec![Event::Started],
                Source::Resume(tokens) => core::iter::once(Event::Resumed).chain(tokens.iter().copied().map(Event::ContextSize)).collect(),
                Source::Compact => vec![],
            },
            Hook::UserPromptSubmit(_) => vec![Event::PromptSubmitted],
            Hook::PermissionRequest(_) => vec![Event::PermissionAsked],
            Hook::PostToolUse(_) => vec![Event::ToolUsed],
            Hook::Stop(stop) => {
                let mut events: Vec<Event> = stop.response_option.iter().cloned().map(Event::Responded).collect();
                events.push(Event::InFlight(stop.background_work_vector.clone()));
                events.push(Event::TurnEnded);
                events
            }
            Hook::SessionEnd(end) => vec![Event::Ended(end.end_reason.clone())],
        }
    }
}

impl Observable for Row {
    fn events(&self) -> Vec<Event> {
        match self {
            Row::Assistant(tokens) => vec![Event::ContextSize(*tokens)],
            Row::TurnStarted => vec![Event::PromptSubmitted],
            // The agents still running as the turn ended, as one set, so the turn ends Waiting while any is.
            Row::TurnEnded(pending_agent_count) => vec![Event::InFlight(pending_agent_count.works()), Event::TurnEnded],
            Row::Interrupted => vec![Event::Interrupted],
            Row::Compacted(compaction) => vec![Event::Compacted(compaction.clone())],
            Row::Other => vec![],
        }
    }
}

impl PendingAgentCount {
    /// The transcript counts the background agents still running as a turn
    /// ends and names none: each is a Subagent, its id saying it was counted.
    pub fn works(&self) -> Vec<BackgroundWork> {
        (1..=self.0.max(0))
            .map(|position| BackgroundWork {
                work_id: WorkId(format!("pending-agent-{position}")),
                work_kind: WorkKind::Subagent,
                description: Description("a background agent the transcript counts as pending, its name not known".into()),
            })
            .collect()
    }
}

impl Processable for ReportProcess {
    type Taken = ReportTaken;
    type Gift = Gift;
    type Outcome = Reporting;

    fn begin<N: Giving<Gift>>(&mut self, mut manager: N) -> Option<Reporting> {
        manager.give(Reported {});
        if let Hook::SessionStart(start) = &self.hook {
            // A session that started is read from its first row; one resumed or compacted from the file's end.
            let read_from = match start.source {
                Source::Startup => ReadFrom::Offset(Offset(0)),
                Source::Resume(_) | Source::Compact => ReadFrom::FileEnd,
            };
            manager.give(Watch { flow_id: start.session_id.identify(), file_path: start.file_path.clone(), read_from });
        }
        manager.give(Observe { flow_id: self.hook.identify(), event_vector: self.hook.events(), offset_option: None });
        None
    }

    fn take<N: Giving<Gift>>(&mut self, taken: ReportTaken, mut manager: N) -> Option<Reporting> {
        match taken {
            ReportTaken::Answer(Answer::Succeeded) => None,
            ReportTaken::Answer(Answer::Failed) => Some(Reporting::Unremembered),
            ReportTaken::Observation(Err(Unremembered {})) => Some(Reporting::Unremembered),
            ReportTaken::Observation(Ok(observation)) => {
                for changed in observation.0 {
                    manager.give(changed)
                }
                Some(Reporting::Observed)
            }
        }
    }
}

impl Processable for WatchProcess {
    type Taken = WatchTaken;
    type Gift = Gift;
    type Outcome = Watching;

    fn begin<N: Giving<Gift>>(&mut self, mut manager: N) -> Option<Watching> {
        manager.give(Follow_Data { file_path: self.file_path.clone(), read_from: self.read_from.clone(), row_count: self.row_count, session_root_option: self.session_root_option.clone() });
        None
    }

    fn take<N: Giving<Gift>>(&mut self, taken: WatchTaken, mut manager: N) -> Option<Watching> {
        match taken {
            WatchTaken::Following(Ok(following)) => {
                self.read_from = ReadFrom::Offset(following.offset);
                // The session's end, when its last process is gone, comes after the rows it wrote.
                let event_vector = following.row_vector.iter().flat_map(Observable::events).chain(following.end_reason_option.map(Event::Ended)).collect();
                manager.give(Observe { flow_id: self.flow_id.clone(), event_vector, offset_option: Some(following.offset) });
                None
            }
            WatchTaken::Following(Err(_)) => Some(Watching::Unfollowed),
            // A Watch goes on when an Observe was not kept: its next carries the later offset.
            WatchTaken::Observation(Err(Unremembered {})) => None,
            WatchTaken::Observation(Ok(observation)) => {
                for changed in observation.0 {
                    manager.give(changed)
                }
                None
            }
        }
    }
}

impl Processable for SubscribeProcess {
    type Taken = SubscribeTaken;
    type Gift = Gift;
    /// It ends one way, when its connection closes, and so declares no outcome.
    type Outcome = ();

    fn begin<N: Giving<Gift>>(&mut self, mut manager: N) -> Option<()> {
        manager.give(Recall {});
        None
    }

    /// It answers with every session as it is now, then rests while its connection is open.
    fn take<N: Giving<Gift>>(&mut self, recollection: SubscribeTaken, mut manager: N) -> Option<()> {
        if let Ok(recollection) = recollection {
            manager.give(Subscribed(recollection.0));
        }
        None
    }
}

impl Processable for ConfigureProcess {
    type Taken = ConfigureTaken;
    type Gift = Gift;
    type Outcome = Configuring;

    fn begin<N: Giving<Gift>>(&mut self, mut manager: N) -> Option<Configuring> {
        manager.give(Keep(self.set.clone()));
        None
    }

    fn take<N: Giving<Gift>>(&mut self, answer: ConfigureTaken, mut manager: N) -> Option<Configuring> {
        match answer {
            Answer::Succeeded => {
                manager.give(Configured(self.set.clone()));
                Some(Configuring::Configured)
            }
            Answer::Failed => Some(Configuring::Unremembered),
        }
    }
}

/// Born of a Prepare, holding the hook client and the hooks as configured then:
/// it gives Install, and answers with the path the translator wrote, or None,
/// the reason for it being its outcome in the trace.
impl Processable for PrepareProcess {
    type Taken = PrepareTaken;
    type Gift = Gift;
    type Outcome = Preparing;

    fn begin<N: Giving<Gift>>(&mut self, mut manager: N) -> Option<Preparing> {
        match &self.hook_client_option {
            Some(hook_client) => {
                manager.give(Install_Data { hook_client: hook_client.clone(), hooks: self.hooks.clone() });
                None
            }
            None => {
                manager.give(Prepared(None));
                Some(Preparing::Unconfigured)
            }
        }
    }

    fn take<N: Giving<Gift>>(&mut self, installation: PrepareTaken, mut manager: N) -> Option<Preparing> {
        let (prepared, preparing) = match installation {
            Ok(Installation_Data::Installed(file_path)) => (Some(file_path), Preparing::Installed),
            Ok(Installation_Data::Uninstalled(_)) => (None, Preparing::Uninstalled),
            Err(_) => (None, Preparing::Unobserved),
        };
        manager.give(Prepared(prepared));
        Some(preparing)
    }
}

/// Born where a transcript root is configured: it gives Discover, and each
/// session the translator finds under the root becomes a Watch of its transcript,
/// read from its first row, since the file is new. It goes on while the
/// translator discovers; an emission that fails ends it Undiscovered.
impl Processable for DiscoverProcess {
    type Taken = DiscoverTaken;
    type Gift = Gift;
    type Outcome = Discovering;

    fn begin<N: Giving<Gift>>(&mut self, mut manager: N) -> Option<Discovering> {
        manager.give(Discover_Data { file_path: self.file_path.clone(), session_root_option: self.session_root_option.clone() });
        None
    }

    fn take<N: Giving<Gift>>(&mut self, taken: DiscoverTaken, mut manager: N) -> Option<Discovering> {
        match taken {
            DiscoverTaken::Discovered(Ok(discovered)) => {
                manager.give(Watch { flow_id: discovered.session_id.identify(), file_path: discovered.file_path, read_from: ReadFrom::Offset(Offset(0)) });
                None
            }
            DiscoverTaken::Discovered(Err(_)) => Some(Discovering::Undiscovered),
            DiscoverTaken::Answer(_) => None,
        }
    }
}
